using System.Diagnostics;
using System.Text.Json;
using ComplianceCaseManagement.Cases;
var commit = Arg("--commit") ?? throw new ArgumentException("--commit required"); var size = int.Parse(Arg("--size") ?? "100000"); var seed = int.Parse(Arg("--seed") ?? "1209"); var runs = int.Parse(Arg("--runs") ?? "10"); var warmups = int.Parse(Arg("--warmups") ?? "2"); var outputPath = Arg("--output"); var random = new Random(seed); var now = DateTimeOffset.UtcNow; var cases = Enumerable.Range(0, size).Select(i => ComplianceCase.Open($"Case {i}", $"owner-{i % 1000}", now.AddMinutes(random.Next(-5000, 5000)), now.AddDays(-1))).ToArray(); long Evaluate() { var sw = Stopwatch.StartNew(); foreach (var item in cases) item.EscalateIfOverdue("benchmark-worker", now); return sw.ElapsedMilliseconds; }
for (var i = 0; i < warmups; i++) { cases = Enumerable.Range(0, size).Select(x => ComplianceCase.Open($"Case {x}", "owner", now.AddMinutes(x % 2 == 0 ? -1 : 1), now.AddDays(-1))).ToArray(); Evaluate(); }
var times = new List<long>(); for (var r = 0; r < runs; r++) { cases = Enumerable.Range(0, size).Select(x => ComplianceCase.Open($"Case {x}", "owner", now.AddMinutes(x % 2 == 0 ? -1 : 1), now.AddDays(-1))).ToArray(); times.Add(Evaluate()); }
times.Sort(); var median = times[times.Count / 2]; var result = new { Commit = commit, Runtime = Environment.Version.ToString(), OS = Environment.OSVersion.ToString(), Environment.ProcessorCount, DatasetGenerator = "ComplianceCaseManagement.Benchmarks/v1", Seed = seed, DatasetSize = size, Concurrency = 1, WarmupRuns = warmups, MeasuredRuns = runs, RawMilliseconds = times, MedianMilliseconds = median, P95Milliseconds = times[(int)Math.Ceiling(times.Count * .95) - 1], MedianCasesPerSecond = median == 0 ? 0 : size * 1000L / median, SchedulingDelay = "In-process evaluation only; persistent worker delay not yet measured" }; var json = JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }); Console.WriteLine(json); if (outputPath is not null) File.WriteAllText(outputPath, json); string? Arg(string n) { var i = Array.IndexOf(args, n); return i >= 0 && i + 1 < args.Length ? args[i + 1] : null; }
